insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:web-designer','AU','web-designer','Web Designer','OSCA','2024 v1.0','2421','AUD',false,'No statutory registration; VETASSESS assesses ANZSCO 232414 Web Designer as Group B','https://www.vetassess.com.au/check-my-occupation/professional-occupations/web-designer','profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
